begin;

-- Shared additive POS migration. Original store_sales rows remain legacy lines.
do $$begin
 if to_regclass('public.store_products') is null or to_regclass('public.store_sales') is null or to_regclass('public.clients') is null
 or to_regprocedure('private.gym_server_now()') is null or to_regprocedure('private.gym_timezone(uuid)') is null
 or to_regprocedure('private.insert_store_audit(uuid,uuid,text,text,text,text,jsonb)') is null then
  raise exception 'La actualización POS requiere Tienda, auditoría y reloj por gimnasio previamente instalados.';
 end if;
end $$;

alter table public.store_products add column if not exists barcode text;
alter table public.store_products add column if not exists description text not null default '';
alter table public.store_products add column if not exists category text not null default '';
alter table public.store_products add column if not exists unit_cost bigint check (unit_cost >= 0);
create unique index if not exists store_products_gym_barcode_unique on public.store_products(gym_id,barcode) where barcode is not null;
create index if not exists store_products_gym_category on public.store_products(gym_id,category);

create table if not exists public.gym_store_settings(
 gym_id uuid primary key references public.gyms(id) on delete cascade,
 enabled boolean not null default true,
 last_sale_number bigint not null default 0 check(last_sale_number>=0),
 updated_by uuid, updated_at timestamptz not null default private.gym_server_now()
);
create table if not exists public.store_orders(
 id uuid primary key default gen_random_uuid(),
 gym_id uuid not null references public.gyms(id) on delete restrict,
 sale_number bigint not null check(sale_number>0), request_id uuid not null,
 request_payload jsonb not null,
 client_id bigint references public.clients(id) on delete restrict,
 customer_name text not null default '', notes text not null default '',
 status text not null default 'COMPLETED' check(status in ('COMPLETED','VOID')),
 total_amount bigint not null check(total_amount>=0),
 sold_by uuid, sold_at timestamptz not null default private.gym_server_now(),
 voided_by uuid, voided_at timestamptz, void_reason text,
 unique(gym_id,sale_number),unique(gym_id,request_id), unique(gym_id,id)
);
alter table public.store_sales add column if not exists order_id uuid references public.store_orders(id) on delete restrict;
alter table public.store_sales add column if not exists unit_cost bigint check(unit_cost>=0);
alter table public.store_sales add column if not exists product_barcode text;
alter table public.store_sales add column if not exists status text not null default 'COMPLETED' check(status in ('COMPLETED','VOID'));
create index if not exists store_orders_gym_date on public.store_orders(gym_id,sold_at desc);
create index if not exists store_orders_gym_client on public.store_orders(gym_id,client_id,sold_at desc);
create index if not exists store_sales_order on public.store_sales(order_id);
create table if not exists public.store_payments(
 id uuid primary key default gen_random_uuid(),gym_id uuid not null,
 order_id uuid not null unique,
 method text not null check(method in ('EFECTIVO','TRANSFERENCIA','TARJETA','OTRO')),
 amount bigint not null check(amount>=0),received bigint not null check(received>=amount),
 change_amount bigint not null check(change_amount=received-amount),
 reference text not null default '',status text not null default 'COMPLETED' check(status in ('COMPLETED','VOID')),
 recorded_by uuid,created_at timestamptz not null default private.gym_server_now(),
 foreign key(gym_id,order_id) references public.store_orders(gym_id,id) on delete restrict
);
create table if not exists public.store_inventory_movements(
 id bigint generated by default as identity primary key,
 gym_id uuid not null references public.gyms(id) on delete restrict,
 product_id bigint not null references public.store_products(id) on delete restrict,
 quantity integer not null,stock_before integer not null check(stock_before>=0),stock_after integer not null check(stock_after>=0),
 movement_type text not null check(movement_type in ('INITIAL_STOCK','SALE','PURCHASE','ADJUSTMENT','RETURN')),
 reference text not null default '',reason text not null default '',
 order_id uuid references public.store_orders(id) on delete restrict,request_id uuid,
 created_by uuid,created_at timestamptz not null default private.gym_server_now(),
 check(stock_after=stock_before+quantity)
);
create index if not exists store_movements_gym_product on public.store_inventory_movements(gym_id,product_id,id desc);
create table if not exists private.store_pos_requests(
 gym_id uuid not null references public.gyms(id) on delete restrict,request_id uuid not null,
 payload jsonb not null,result jsonb not null,primary key(gym_id,request_id)
);
-- A private transaction capability cannot be forged by set_config on an API session.
create table if not exists private.store_pos_context(
 transaction_id bigint primary key, movement_type text,reference text default '',reason text default '',
 order_id uuid,request_id uuid
);
revoke all on private.store_pos_context,private.store_pos_requests from public,anon,authenticated;

create or replace function private.store_pos_authorize(p_gym_id uuid,p_admin boolean default false,p_require_enabled boolean default true)
returns void language plpgsql security definer set search_path='' as $$
begin
 if auth.uid() is null or not private.user_has_gym_role(p_gym_id,case when p_admin then array['admin'] else array['admin','receptionist'] end) then
  raise exception 'No tienes permiso para esta operación de tienda.' using errcode='42501';end if;
 if p_require_enabled and not coalesce((select enabled from public.gym_store_settings where gym_id=p_gym_id),true) then
  raise exception 'La tienda está deshabilitada en este gimnasio.' using errcode='42501';end if;
end $$;

create or replace function private.store_pos_guard() returns trigger
language plpgsql set search_path='' as $$
begin
 if current_user in ('authenticated','anon') then raise exception 'El historial POS es inmutable; utiliza los procedimientos autorizados.' using errcode='42501';end if;
 if not exists(select 1 from private.store_pos_context where transaction_id=txid_current()) then
  if tg_table_name='store_sales' then
   if (case when tg_op='DELETE' then old.order_id is null when tg_op='INSERT' then new.order_id is null else old.order_id is null and new.order_id is null end) then
    return case when tg_op='DELETE' then old else new end;
   end if;
  end if;
  raise exception 'El historial POS es inmutable; utiliza los procedimientos autorizados.' using errcode='42501';
 end if;
 return case when tg_op='DELETE' then old else new end;
end $$;
