create or replace function private.store_pos_product_guard() returns trigger
language plpgsql set search_path='' as $$
begin
 -- API callers cannot overwrite stock directly. Existing definer RPCs retain their contracts.
 if current_user in ('authenticated','anon') then
  raise exception 'Usa los procedimientos de productos o inventario para cambiar el catálogo.' using errcode='42501';end if;
 if tg_op='DELETE' then return old;end if;
 if new.barcode is not null then
  new.barcode:=nullif(trim(new.barcode),'');
  if not private.store_pos_valid_barcode(new.barcode) then raise exception 'Código de barras inválido (máximo 128 caracteres).';end if;
 end if;
 if tg_op='UPDATE' and new.gym_id<>old.gym_id then raise exception 'No se puede mover un producto entre gimnasios.';end if;
 return new;
end $$;
create or replace function private.store_pos_stock_ledger() returns trigger
language plpgsql security definer set search_path='' as $$
declare ctx private.store_pos_context; previous integer; delta integer;
begin
 previous:=case when tg_op='INSERT' then 0 else old.stock_quantity end; delta:=new.stock_quantity-previous;
 if tg_op='UPDATE' and delta=0 then return new;end if;
 select * into ctx from private.store_pos_context where transaction_id=txid_current();
 insert into public.store_inventory_movements(gym_id,product_id,quantity,stock_before,stock_after,movement_type,reference,reason,order_id,request_id,created_by,created_at)
 values(new.gym_id,new.id,delta,previous,new.stock_quantity,
 coalesce(ctx.movement_type,case when tg_op='INSERT' then 'INITIAL_STOCK' else 'ADJUSTMENT' end),
 coalesce(ctx.reference,'Producto '||new.id),coalesce(ctx.reason,'Cambio mediante API histórica autorizada'),ctx.order_id,ctx.request_id,auth.uid(),private.gym_server_now());
 return new;
end $$;
-- Ledger writes triggered by a legacy definer API are authorized inside this trigger.
create or replace function private.store_pos_movement_guard() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if tg_op='INSERT' and pg_trigger_depth()>1 then return new;end if;
 if not exists(select 1 from private.store_pos_context where transaction_id=txid_current()) then
  raise exception 'Los movimientos de inventario no se pueden modificar directamente.' using errcode='42501';end if;
 return case when tg_op='DELETE' then old else new end;
end $$;

drop trigger if exists store_pos_product_guard on public.store_products;
create trigger store_pos_product_guard before insert or update or delete on public.store_products for each row execute function private.store_pos_product_guard();
-- Snapshot only the current balance; never invent a historical opening instant.
insert into private.store_pos_context(transaction_id,movement_type,reason) values(txid_current(),'INITIAL_STOCK','Saldo al instalar POS') on conflict do nothing;
insert into public.store_inventory_movements(gym_id,product_id,quantity,stock_before,stock_after,movement_type,reference,reason,created_at)
select p.gym_id,p.id,p.stock_quantity,0,p.stock_quantity,'INITIAL_STOCK','Migración POS','Saldo al instalar POS',private.gym_server_now()
from public.store_products p where not exists(select 1 from public.store_inventory_movements m where m.product_id=p.id);
delete from private.store_pos_context where transaction_id=txid_current();
drop trigger if exists store_pos_stock_ledger on public.store_products;
create trigger store_pos_stock_ledger after insert or update of stock_quantity on public.store_products for each row execute function private.store_pos_stock_ledger();
drop trigger if exists store_pos_guard on public.store_orders;
create trigger store_pos_guard before insert or update or delete on public.store_orders for each row execute function private.store_pos_guard();
drop trigger if exists store_pos_guard on public.store_sales;
create trigger store_pos_guard before insert or update or delete on public.store_sales for each row execute function private.store_pos_guard();
drop trigger if exists store_pos_guard on public.store_payments;
create trigger store_pos_guard before insert or update or delete on public.store_payments for each row execute function private.store_pos_guard();
drop trigger if exists store_pos_guard on public.store_inventory_movements;
create trigger store_pos_guard before insert or update or delete on public.store_inventory_movements for each row execute function private.store_pos_movement_guard();

create or replace function public.store_pos_settings(p_gym_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
 perform private.store_pos_authorize(p_gym_id,false,false);
 return jsonb_build_object('enabled',coalesce((select enabled from public.gym_store_settings where gym_id=p_gym_id),true),
 'timezone',private.gym_timezone(p_gym_id),'server_now',private.gym_server_now(),'payment_methods',jsonb_build_array('EFECTIVO','TRANSFERENCIA','TARJETA','OTRO'));
end $$;
create or replace function public.store_pos_configure(p_gym_id uuid,p_enabled boolean) returns jsonb
language plpgsql security definer set search_path='' as $$
begin
 perform private.store_pos_authorize(p_gym_id,true,false);
 if p_enabled is null then raise exception 'Selecciona si la tienda está habilitada.';end if;
 insert into public.gym_store_settings(gym_id,enabled,updated_by) values(p_gym_id,p_enabled,auth.uid())
 on conflict(gym_id) do update set enabled=excluded.enabled,updated_by=excluded.updated_by,updated_at=private.gym_server_now();
 perform private.insert_store_audit(p_gym_id,auth.uid(),'STORE_CONFIGURED','gym_store_settings',p_gym_id::text,'Configuración de tienda',jsonb_build_object('enabled',p_enabled));
 return public.store_pos_settings(p_gym_id);
end $$;
create or replace function public.store_pos_products(p_gym_id uuid,p_search text default '',p_include_inactive boolean default false) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare admin boolean;result jsonb;
begin
 perform private.store_pos_authorize(p_gym_id);admin:=private.user_has_gym_role(p_gym_id,array['admin']);
 select coalesce(jsonb_agg((to_jsonb(p)-'gym_id'-'created_by'-'updated_by'-'unit_cost')||
 case when admin then jsonb_build_object('unit_cost',p.unit_cost) else '{}'::jsonb end||jsonb_build_object('available',p.stock_quantity>0,'stock_status',case when not p.active then 'INACTIVO' when p.stock_quantity=0 then 'AGOTADO' when p.stock_quantity<=p.low_stock_threshold then 'POCAS UNIDADES' else 'DISPONIBLE' end) order by p.active desc,p.name),'[]') into result
 from public.store_products p where p.gym_id=p_gym_id and (p.active or (admin and p_include_inactive))
 and (coalesce(trim(p_search),'')='' or concat_ws(' ',p.name,p.sku,p.barcode,p.category) ilike '%'||trim(p_search)||'%');
 return result;
end $$;
create or replace function public.store_pos_save_product(p_gym_id uuid,p_product_id bigint,p_data jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare p public.store_products;oldp public.store_products; k text; stock integer; image text;
begin
 perform private.store_pos_authorize(p_gym_id,true);
 if jsonb_typeof(p_data) is distinct from 'object' then raise exception 'Datos de producto inválidos.';end if;
 for k in select jsonb_object_keys(p_data) loop
  if not k=any(array['name','sku','barcode','description','category','unit_cost','sale_price','stock_quantity','low_stock_threshold','active','image_data']) then raise exception 'Campo de producto no permitido: %.',k;end if;
 end loop;
 if p_product_id is not null then
  select * into oldp from public.store_products where gym_id=p_gym_id and id=p_product_id for update;
  if not found then raise exception 'Producto no encontrado.';end if;
  if p_data ? 'stock_quantity' and (p_data->>'stock_quantity')::integer<>oldp.stock_quantity then raise exception 'Usa entrada o ajuste de inventario para cambiar el stock.';end if;
 end if;
 p:=jsonb_populate_record(oldp,p_data);stock:=coalesce(p.stock_quantity,0);image:=coalesce(p.image_data,'');
 if trim(coalesce(p.name,''))='' or coalesce(p.sale_price,-1)<0 or stock<0 or coalesce(p.low_stock_threshold,5)<0 or p.unit_cost<0 then raise exception 'Revisa el nombre, precio, costo y cantidades del producto.';end if;
 if image<>'' and image not like 'data:image/%;base64,%' then raise exception 'La foto del producto no tiene un formato válido.';end if;
 if p_product_id is null then
  insert into public.store_products(gym_id,name,sku,barcode,description,category,unit_cost,sale_price,stock_quantity,low_stock_threshold,active,image_data,created_by,updated_by,created_at,updated_at)
  values(p_gym_id,trim(p.name),upper(trim(coalesce(p.sku,''))),nullif(trim(p.barcode),''),coalesce(p.description,''),trim(coalesce(p.category,'')),p.unit_cost,p.sale_price,stock,coalesce(p.low_stock_threshold,5),coalesce(p.active,true),image,auth.uid(),auth.uid(),private.gym_server_now(),private.gym_server_now()) returning * into p;
 else
  update public.store_products set name=trim(p.name),sku=upper(trim(coalesce(p.sku,''))),barcode=nullif(trim(p.barcode),''),description=coalesce(p.description,''),category=trim(coalesce(p.category,'')),unit_cost=p.unit_cost,sale_price=p.sale_price,low_stock_threshold=coalesce(p.low_stock_threshold,5),active=coalesce(p.active,true),image_data=image,updated_by=auth.uid(),updated_at=private.gym_server_now()
  where gym_id=p_gym_id and id=p_product_id returning * into p;
 end if;
 perform private.insert_store_audit(p_gym_id,auth.uid(),case when p_product_id is null then 'PRODUCT_CREATED' else 'PRODUCT_UPDATED' end,'store_products',p.id::text,p.name,jsonb_build_object('barcode',p.barcode,'category',p.category));
 if p_product_id is not null and p.sale_price is distinct from oldp.sale_price then perform private.insert_store_audit(p_gym_id,auth.uid(),'PRICE_CHANGED','store_products',p.id::text,p.name,jsonb_build_object('before',oldp.sale_price,'after',p.sale_price));end if;
 if p.unit_cost is distinct from oldp.unit_cost then perform private.insert_store_audit(p_gym_id,auth.uid(),'COST_CHANGED','store_products',p.id::text,p.name,jsonb_build_object('before',oldp.unit_cost,'after',p.unit_cost));end if;
 return to_jsonb(p)-'gym_id'-'created_by'-'updated_by';
exception when unique_violation then raise exception 'Ya existe un producto con ese nombre, SKU o código de barras en este gimnasio.' using errcode='23505';
end $$;

create or replace function private.store_pos_receipt(p_gym_id uuid,p_order_id uuid) returns jsonb
language sql stable security definer set search_path='' as $$
 select (to_jsonb(o)-'request_payload'-'gym_id')||jsonb_build_object('order_id',o.id,
 'number','V-'||lpad(o.sale_number::text,6,'0'),'timezone',private.gym_timezone(o.gym_id),
 'actor_role',coalesce(gu.role,'system'),'actor_email',coalesce(au.email,'Sistema'),
 'items',(select coalesce(jsonb_agg((to_jsonb(s)-'gym_id'-'unit_cost')||case when private.user_has_gym_role(p_gym_id,array['admin']) then jsonb_build_object('unit_cost',s.unit_cost) else '{}'::jsonb end order by s.id),'[]') from public.store_sales s where s.order_id=o.id and s.gym_id=o.gym_id),
 'payment',(select to_jsonb(p)-'gym_id' from public.store_payments p where p.order_id=o.id and p.gym_id=o.gym_id))
 from public.store_orders o left join public.gym_users gu on gu.gym_id=o.gym_id and gu.user_id=o.sold_by left join auth.users au on au.id=o.sold_by
 where o.gym_id=p_gym_id and o.id=p_order_id
$$;

create or replace function public.store_pos_checkout(p_gym_id uuid,p_request_id uuid,p_items jsonb,p_payment jsonb,p_client_id bigint default null,p_customer_name text default '',p_notes text default '') returns jsonb
language plpgsql security definer set search_path='' as $$
declare payload jsonb; previous public.store_orders; o public.store_orders; p public.store_products; item jsonb; total bigint:=0; amount bigint;qty integer;method text;received bigint;num bigint;at_time timestamptz:=private.gym_server_now();
begin
 perform private.store_pos_authorize(p_gym_id,false,false);
 if p_request_id is null then raise exception 'Falta la referencia idempotente del cobro.';end if;
 payload:=jsonb_build_object('items',p_items,'payment',p_payment,'client_id',p_client_id,'customer_name',coalesce(p_customer_name,''),'notes',coalesce(p_notes,''));
 perform pg_advisory_xact_lock(hashtextextended(p_gym_id::text||':checkout:'||p_request_id::text,0));
 select * into previous from public.store_orders where gym_id=p_gym_id and request_id=p_request_id;
 if found then
  if previous.request_payload<>payload or previous.sold_by is distinct from auth.uid() then raise exception 'La referencia de cobro ya fue utilizada con otros datos.';end if;
  return private.store_pos_receipt(p_gym_id,previous.id)||jsonb_build_object('duplicate',true);
 end if;
 perform private.store_pos_authorize(p_gym_id);
 if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) not between 1 and 200 then raise exception 'Agrega productos al carrito (máximo 200).' using errcode='GS001';end if;
 if jsonb_typeof(p_payment) is distinct from 'object' then raise exception 'Selecciona un método de pago.' using errcode='GS001';end if;
 method:=upper(trim(coalesce(p_payment->>'method','')));
 if method not in ('EFECTIVO','TRANSFERENCIA','TARJETA','OTRO') then raise exception 'El método de pago no es válido.' using errcode='GS001';end if;
 if exists(select 1 from jsonb_array_elements(p_items) x where jsonb_typeof(x)<>'object' or not(x ?& array['product_id','quantity','expected_price']) or coalesce(x->>'quantity','') !~ '^[1-9][0-9]*$' or coalesce(x->>'product_id','') !~ '^[1-9][0-9]*$' or coalesce(x->>'expected_price','') !~ '^[0-9]+$') then raise exception 'Cada línea requiere producto, cantidad entera y precio esperado.' using errcode='GS001';end if;
 if (select count(distinct (x->>'product_id')::bigint) from jsonb_array_elements(p_items) x)<>jsonb_array_length(p_items) then raise exception 'Agrupa las cantidades de cada producto en una sola línea.' using errcode='GS001';end if;
 if p_client_id is not null and not exists(select 1 from public.clients where gym_id=p_gym_id and id=p_client_id) then raise exception 'El cliente no pertenece a este gimnasio.' using errcode='GS001';end if;
 -- Acquire every product lock in the same order before calculating or mutating stock.
 perform locked.id from public.store_products locked where locked.gym_id=p_gym_id and locked.id in(select (x->>'product_id')::bigint from jsonb_array_elements(p_items) x) order by locked.id for update;
 for item in select x from jsonb_array_elements(p_items) x order by (x->>'product_id')::bigint loop
  select * into p from public.store_products where gym_id=p_gym_id and id=(item->>'product_id')::bigint;
  if not found or not p.active then raise exception 'El producto no existe o está desactivado.' using errcode='GS001';end if;
  qty:=(item->>'quantity')::integer;
  if p.stock_quantity<qty then raise exception 'Existencias insuficientes para %. Stock disponible: %.',p.name,p.stock_quantity using errcode='GS001';end if;
  if p.sale_price<>(item->>'expected_price')::bigint then raise exception 'El precio de % cambió; actualiza el carrito antes de cobrar.',p.name using errcode='GS001';end if;
  total:=total+p.sale_price*qty;
 end loop;
 if method='EFECTIVO' then
  if coalesce(p_payment->>'received','') !~ '^[0-9]+$' then raise exception 'Indica el efectivo recibido.' using errcode='GS001';end if;
  received:=(p_payment->>'received')::bigint;
  if received<total then raise exception 'El efectivo recibido es menor que el total.' using errcode='GS001';end if;
 else received:=total;end if;
 insert into public.gym_store_settings(gym_id) values(p_gym_id) on conflict do nothing;
 update public.gym_store_settings set last_sale_number=last_sale_number+1 where gym_id=p_gym_id returning last_sale_number into num;
 insert into private.store_pos_context(transaction_id,movement_type,reference,reason,request_id) values(txid_current(),'SALE','V-'||lpad(num::text,6,'0'),'Venta POS',p_request_id);
 insert into public.store_orders(gym_id,sale_number,request_id,request_payload,client_id,customer_name,notes,total_amount,sold_by,sold_at)
 values(p_gym_id,num,p_request_id,payload,p_client_id,trim(coalesce(p_customer_name,'')),trim(coalesce(p_notes,'')),total,auth.uid(),at_time) returning * into o;
 update private.store_pos_context set order_id=o.id where transaction_id=txid_current();
 for item in select x from jsonb_array_elements(p_items) x order by (x->>'product_id')::bigint loop
  select * into p from public.store_products where gym_id=p_gym_id and id=(item->>'product_id')::bigint;qty:=(item->>'quantity')::integer;
  insert into public.store_sales(gym_id,order_id,product_id,product_name,product_sku,product_barcode,quantity,unit_price,unit_cost,total_amount,payment_method,payment_reference,customer_name,notes,sold_by,sold_at)
  values(p_gym_id,o.id,p.id,p.name,p.sku,p.barcode,qty,p.sale_price,p.unit_cost,p.sale_price*qty,method,trim(coalesce(p_payment->>'reference','')),o.customer_name,o.notes,auth.uid(),at_time);
  update public.store_products set stock_quantity=stock_quantity-qty,updated_by=auth.uid(),updated_at=at_time where id=p.id and gym_id=p_gym_id;
 end loop;
 insert into public.store_payments(gym_id,order_id,method,amount,received,change_amount,reference,recorded_by,created_at)
 values(p_gym_id,o.id,method,total,received,received-total,trim(coalesce(p_payment->>'reference','')),auth.uid(),at_time);
 perform private.insert_store_audit(p_gym_id,auth.uid(),'SALE_COMPLETED','store_orders',o.id::text,'Venta '||num,jsonb_build_object('total_amount',total,'method',method,'sale_number',num));
 delete from private.store_pos_context where transaction_id=txid_current();
 return private.store_pos_receipt(p_gym_id,o.id)||jsonb_build_object('duplicate',false);
end $$;

create or replace function public.store_pos_inventory(p_gym_id uuid,p_request_id uuid,p_product_id bigint,p_mode text,p_quantity integer,p_reason text default '',p_unit_cost bigint default null,p_expected_stock integer default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare p public.store_products; mode text:=upper(trim(coalesce(p_mode,'')));payload jsonb;prev private.store_pos_requests;after_stock integer;movement public.store_inventory_movements;result jsonb;
begin
 perform private.store_pos_authorize(p_gym_id,true,false);
 if p_request_id is null then raise exception 'Falta referencia de inventario.';end if;
 payload:=jsonb_build_object('product_id',p_product_id,'mode',p_mode,'quantity',p_quantity,'reason',p_reason,'unit_cost',p_unit_cost,'expected_stock',p_expected_stock,'actor',auth.uid());
 perform pg_advisory_xact_lock(hashtextextended(p_gym_id::text||':inventory:'||p_request_id::text,0));
 select * into prev from private.store_pos_requests where gym_id=p_gym_id and request_id=p_request_id;
 if found then if prev.payload<>payload then raise exception 'La referencia de inventario ya fue utilizada con otros datos.';end if;return prev.result||jsonb_build_object('duplicate',true);end if;
 perform private.store_pos_authorize(p_gym_id,true);
 if mode not in ('RECEIVE','ADJUST') or p_quantity is null or p_unit_cost<0 then raise exception 'Entrada o ajuste de inventario inválido.' using errcode='GS001';end if;
 if mode='RECEIVE' and p_quantity<=0 then raise exception 'La cantidad recibida debe ser positiva.' using errcode='GS001';end if;
 if mode='ADJUST' and (p_quantity<0 or p_expected_stock is null or trim(coalesce(p_reason,''))='') then raise exception 'El ajuste requiere conteo físico, stock esperado y motivo.' using errcode='GS001';end if;
 select * into p from public.store_products where gym_id=p_gym_id and id=p_product_id for update;
 if not found then raise exception 'Producto no encontrado.' using errcode='GS001';end if;
 if p_expected_stock is not null and p_expected_stock<>p.stock_quantity then raise exception 'El stock cambió. Actualiza antes de confirmar.' using errcode='GS001';end if;
 after_stock:=case when mode='RECEIVE' then p.stock_quantity+p_quantity else p_quantity end;
 insert into private.store_pos_context(transaction_id,movement_type,reference,reason,request_id) values(txid_current(),case when mode='RECEIVE' then 'PURCHASE' else 'ADJUSTMENT' end,p_request_id::text,trim(coalesce(p_reason,'')),p_request_id);
 update public.store_products set stock_quantity=after_stock,unit_cost=coalesce(p_unit_cost,unit_cost),updated_by=auth.uid(),updated_at=private.gym_server_now() where gym_id=p_gym_id and id=p_product_id;
 -- Even a confirmed zero-difference physical count has its own audit movement.
 if after_stock=p.stock_quantity then insert into public.store_inventory_movements(gym_id,product_id,quantity,stock_before,stock_after,movement_type,reference,reason,request_id,created_by) values(p_gym_id,p.id,0,p.stock_quantity,after_stock,'ADJUSTMENT',p_request_id::text,trim(p_reason),p_request_id,auth.uid());end if;
 select * into movement from public.store_inventory_movements where gym_id=p_gym_id and request_id=p_request_id order by id desc limit 1;
 perform private.insert_store_audit(p_gym_id,auth.uid(),case when mode='RECEIVE' then 'INVENTORY_RECEIVED' else 'INVENTORY_ADJUSTED' end,'store_products',p.id::text,p.name,to_jsonb(movement));
 if p_unit_cost is not null and p_unit_cost is distinct from p.unit_cost then perform private.insert_store_audit(p_gym_id,auth.uid(),'COST_CHANGED','store_products',p.id::text,p.name,jsonb_build_object('before',p.unit_cost,'after',p_unit_cost));end if;
 result:=jsonb_build_object('product_id',p.id,'stock_before',p.stock_quantity,'stock_after',after_stock,'stock_quantity',after_stock,'movement',to_jsonb(movement),'duplicate',false);
 insert into private.store_pos_requests(gym_id,request_id,payload,result) values(p_gym_id,p_request_id,payload,result);
 delete from private.store_pos_context where transaction_id=txid_current();return result;
end $$;

create or replace function public.store_pos_void(p_gym_id uuid,p_order_id uuid,p_reason text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare o public.store_orders;line public.store_sales;
begin
 perform private.store_pos_authorize(p_gym_id,true);
 if trim(coalesce(p_reason,''))='' then raise exception 'Indica un motivo para anular la venta.';end if;
 select * into o from public.store_orders where gym_id=p_gym_id and id=p_order_id for update;
 if not found then raise exception 'Venta no encontrada.';end if;
 if o.status='VOID' then return private.store_pos_receipt(p_gym_id,o.id)||jsonb_build_object('duplicate',true);end if;
 perform p.id from public.store_products p where p.gym_id=p_gym_id and p.id in(select product_id from public.store_sales where order_id=o.id) order by p.id for update;
 insert into private.store_pos_context(transaction_id,movement_type,reference,reason,order_id) values(txid_current(),'RETURN','V-'||lpad(o.sale_number::text,6,'0'),trim(p_reason),o.id);
 for line in select * from public.store_sales where order_id=o.id and gym_id=p_gym_id order by product_id loop
  update public.store_products set stock_quantity=stock_quantity+line.quantity,updated_by=auth.uid(),updated_at=private.gym_server_now() where gym_id=p_gym_id and id=line.product_id;
 end loop;
 update public.store_orders set status='VOID',voided_by=auth.uid(),voided_at=private.gym_server_now(),void_reason=trim(p_reason) where id=o.id;
 update public.store_sales set status='VOID' where order_id=o.id;
 update public.store_payments set status='VOID' where order_id=o.id;
 perform private.insert_store_audit(p_gym_id,auth.uid(),'SALE_VOIDED','store_orders',o.id::text,'Venta anulada',jsonb_build_object('reason',trim(p_reason),'total_amount',o.total_amount));
 delete from private.store_pos_context where transaction_id=txid_current();
 return private.store_pos_receipt(p_gym_id,o.id)||jsonb_build_object('duplicate',false);
end $$;

create or replace function public.store_pos_history(p_gym_id uuid,p_filters jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare result jsonb;admin boolean;from_date date;to_date date;period text;today date:=private.gym_local_date(p_gym_id);
begin
 perform private.store_pos_authorize(p_gym_id,false,false);admin:=private.user_has_gym_role(p_gym_id,array['admin']);
 if nullif(p_filters->>'request_id','') is not null then
  select coalesce(jsonb_agg(private.store_pos_receipt(p_gym_id,o.id)),'[]') into result from public.store_orders o
  where o.gym_id=p_gym_id and o.request_id=(p_filters->>'request_id')::uuid and (admin or o.sold_by=auth.uid());
  return result;
 end if;
 period:=coalesce(p_filters->>'period','');
 from_date:=coalesce(nullif(coalesce(p_filters->>'date_from',p_filters->>'from'),'')::date,case period when 'today' then today when 'week' then date_trunc('week',today)::date when 'month' then date_trunc('month',today)::date else today-30 end);
 to_date:=coalesce(nullif(coalesce(p_filters->>'date_to',p_filters->>'to'),'')::date,today);
 if from_date>to_date or to_date-from_date>730 then raise exception 'Período de consulta inválido.';end if;
 select coalesce(jsonb_agg(private.store_pos_receipt(p_gym_id,o.id) order by o.sold_at desc,o.sale_number desc),'[]') into result from
 (select * from public.store_orders o where o.gym_id=p_gym_id and (admin or o.sold_by=auth.uid())
 and (o.sold_at at time zone private.gym_timezone(p_gym_id))::date between from_date and to_date
 and (nullif(p_filters->>'order_id','') is null or o.id=(p_filters->>'order_id')::uuid)
 and (nullif(p_filters->>'request_id','') is null or o.request_id=(p_filters->>'request_id')::uuid)
 and (nullif(coalesce(p_filters->>'employee_id',p_filters->>'sold_by'),'') is null or o.sold_by=coalesce(p_filters->>'employee_id',p_filters->>'sold_by')::uuid)
 and (nullif(p_filters->>'client_id','') is null or o.client_id=(p_filters->>'client_id')::bigint)
 and (nullif(p_filters->>'status','') is null or o.status=upper(p_filters->>'status'))
 and (nullif(p_filters->>'product_id','') is null or exists(select 1 from public.store_sales s where s.order_id=o.id and s.product_id=(p_filters->>'product_id')::bigint))
 order by o.sold_at desc,o.sale_number desc limit least(greatest(coalesce((p_filters->>'limit')::integer,100),1),500)) o;
 return result;
end $$;
create or replace function public.store_pos_movements(p_gym_id uuid,p_product_id bigint default null) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare result jsonb;
begin
 perform private.store_pos_authorize(p_gym_id,true);
 select coalesce(jsonb_agg(to_jsonb(m) order by m.id desc),'[]') into result from(select * from public.store_inventory_movements where gym_id=p_gym_id and (p_product_id is null or product_id=p_product_id) order by id desc limit 500) m;
 return result;
end $$;

create or replace function public.store_pos_stats(p_gym_id uuid,p_filters jsonb default '{}') returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare result jsonb;today date:=private.gym_local_date(p_gym_id);from_date date;to_date date;
begin
 perform private.store_pos_authorize(p_gym_id,true);
 from_date:=coalesce(nullif(coalesce(p_filters->>'date_from',p_filters->>'from'),'')::date,date_trunc('month',today)::date);
 to_date:=coalesce(nullif(coalesce(p_filters->>'date_to',p_filters->>'to'),'')::date,today);
 if from_date>to_date or to_date-from_date>730 then raise exception 'Período de consulta inválido.';end if;
 with all_sales as(select s.*,(s.sold_at at time zone private.gym_timezone(p_gym_id))::date sale_date from public.store_sales s where s.gym_id=p_gym_id and s.status='COMPLETED'),
 sales as(select * from all_sales where sale_date between from_date and to_date),
 products as(select * from public.store_products where gym_id=p_gym_id and active)
 select jsonb_build_object('date_from',from_date,'date_to',to_date,'timezone',private.gym_timezone(p_gym_id),
 'today',coalesce((select sum(total_amount) from all_sales where sale_date=today),0),
 'today_count',(select count(distinct coalesce(order_id::text,'legacy-'||id)) from all_sales where sale_date=today),
 'week_count',(select count(distinct coalesce(order_id::text,'legacy-'||id)) from all_sales where sale_date between date_trunc('week',today)::date and today),
 'month_count',(select count(distinct coalesce(order_id::text,'legacy-'||id)) from all_sales where sale_date between date_trunc('month',today)::date and today),
 'week',coalesce((select sum(total_amount) from all_sales where sale_date between date_trunc('week',today)::date and today),0),
 'month',coalesce((select sum(total_amount) from all_sales where sale_date between date_trunc('month',today)::date and today),0),
 'store_income',coalesce((select sum(total_amount) from sales),0),
 'sale_count',(select count(distinct coalesce(order_id::text,'legacy-'||id)) from sales),
 'units_sold',coalesce((select sum(quantity) from sales),0),
 'cost_complete',coalesce((select bool_and(unit_cost is not null) from sales),false),
 'gross_profit',(select case when count(*)>0 and bool_and(unit_cost is not null) then sum(total_amount-unit_cost*quantity) else null end from sales),
 'known_cost_revenue',coalesce((select sum(total_amount) from sales where unit_cost is not null),0),
 'unknown_cost_units',coalesce((select sum(quantity) from sales where unit_cost is null),0),
 'top_products',coalesce((select jsonb_agg(to_jsonb(t) order by revenue desc) from(select product_id,product_name,sum(quantity)::bigint quantity,sum(total_amount)::bigint total_amount,sum(total_amount)::bigint revenue from sales group by product_id,product_name order by revenue desc limit 20)t),'[]'),
 'low_stock',coalesce((select jsonb_agg(jsonb_build_object('id',id,'name',name,'stock_quantity',stock_quantity,'low_stock_threshold',low_stock_threshold) order by stock_quantity,name) from products where stock_quantity<=low_stock_threshold),'[]'),
 'out_of_stock',(select count(*) from products where stock_quantity=0)) into result;
 return result;
end $$;

-- Keep the historic single-product API, now backed by the atomic POS transaction.
create or replace function public.register_store_sale(p_gym_id uuid,p_product_id bigint,p_quantity integer,p_payment_method text,p_payment_reference text,p_customer_name text,p_notes text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare price bigint;receipt jsonb;line jsonb;
begin
 perform private.store_pos_authorize(p_gym_id);
 select sale_price into price from public.store_products where gym_id=p_gym_id and id=p_product_id;
 receipt:=public.store_pos_checkout(p_gym_id,gen_random_uuid(),jsonb_build_array(jsonb_build_object('product_id',p_product_id,'quantity',p_quantity,'expected_price',price)),jsonb_build_object('method',upper(coalesce(nullif(trim(p_payment_method),''),'EFECTIVO')),'received',price*p_quantity,'reference',p_payment_reference),null,p_customer_name,p_notes);
 line:=receipt->'items'->0;
 return jsonb_build_object('sale_id',line->'id','order_id',receipt->'id','product_id',p_product_id,'product_name',line->'product_name','quantity',p_quantity,'unit_price',price,'total_amount',receipt->'total_amount','stock_remaining',(select stock_quantity from public.store_products where id=p_product_id),'sold_at',receipt->'sold_at');
end $$;
-- Legacy catalog APIs use the same barcode search and enabled guard.
create or replace function public.admin_list_store_products(p_gym_id uuid,p_search text default '',p_include_inactive boolean default true) returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin perform private.store_pos_authorize(p_gym_id,true);return public.store_pos_products(p_gym_id,p_search,p_include_inactive);end $$;
create or replace function public.reception_list_store_products(p_gym_id uuid,p_search text default '') returns jsonb
language sql stable security definer set search_path='' as $$select public.store_pos_products(p_gym_id,p_search,false)$$;

-- Historical product editor remains available and shares stock/enabled validation.
create or replace function public.admin_save_store_product(p_gym_id uuid,p_product_id bigint,p_name text,p_sku text,p_sale_price bigint,p_stock_quantity integer,p_low_stock_threshold integer,p_active boolean,p_image_data text default '') returns bigint
language plpgsql security definer set search_path='' as $$
declare result jsonb;
begin
 result:=public.store_pos_save_product(p_gym_id,p_product_id,jsonb_build_object('name',p_name,'sku',p_sku,'sale_price',p_sale_price,'stock_quantity',p_stock_quantity,'low_stock_threshold',p_low_stock_threshold,'active',p_active,'image_data',p_image_data));
 return (result->>'id')::bigint;
end $$;

-- Keep existing finance shape, but count complete orders and exclude voided lines.
create or replace function public.admin_store_finance(p_gym_id uuid,p_date_from date,p_date_to date) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_from date:=coalesce(p_date_from,date_trunc('month',private.gym_local_date(p_gym_id))::date);v_to date:=coalesce(p_date_to,private.gym_local_date(p_gym_id));result jsonb;
begin
 perform private.store_pos_authorize(p_gym_id,true,false);
 if v_from>v_to or v_to-v_from>730 then raise exception 'El período de consulta no es válido.';end if;
 with sales as(select s.*,coalesce(o.id::text,'legacy-'||s.id) transaction_id,coalesce(au.email,'Sistema') actor_email,coalesce(gu.role,'system') actor_role
 from public.store_sales s left join public.store_orders o on o.id=s.order_id left join auth.users au on au.id=s.sold_by left join public.gym_users gu on gu.gym_id=s.gym_id and gu.user_id=s.sold_by
 where s.gym_id=p_gym_id and s.status='COMPLETED' and (s.sold_at at time zone private.gym_timezone(p_gym_id))::date between v_from and v_to)
 select jsonb_build_object('date_from',v_from,'date_to',v_to,'store_income',coalesce((select sum(total_amount) from sales),0),
 'sale_count',(select count(distinct transaction_id) from sales),
 'average_sale',coalesce((select round(sum(total_amount)::numeric/nullif(count(distinct transaction_id),0))::bigint from sales),0),
 'by_product',coalesce((select jsonb_agg(to_jsonb(t) order by total desc,label) from(select product_name label,sum(quantity)::bigint count,count(distinct transaction_id) transactions,sum(total_amount)::bigint total from sales group by product_name)t),'[]'),
 'by_method',coalesce((select jsonb_agg(to_jsonb(t) order by total desc,label) from(select payment_method label,count(distinct transaction_id) count,sum(total_amount)::bigint total from sales group by payment_method)t),'[]'),
 'sales',coalesce((select jsonb_agg(to_jsonb(s)-'unit_cost'-'transaction_id' order by sold_at desc,id desc) from sales s),'[]')) into result;
 return result;
end $$;

-- No new table is a direct write API; all reads go through role-aware RPCs.
do $$declare t text;f record;begin
 foreach t in array array['store_orders','store_payments','store_inventory_movements','gym_store_settings'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated',t);
 end loop;
 for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname like 'store_pos_%' loop
  execute format('revoke all on function %s from public,anon,authenticated',f.signature);
 end loop;
 for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'store_pos_%' loop
  execute format('revoke all on function %s from public,anon,authenticated',f.signature);
  execute format('grant execute on function %s to authenticated',f.signature);
 end loop;
end $$;
commit;
